<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\ContractRenewal;
use App\Models\Employee;
use App\Models\Grievance;
use Illuminate\Http\Request;
use Illuminate\Http\RedirectResponse;
use Illuminate\View\View;
class ComplianceController extends Controller { public function renewals():View{$renewals=ContractRenewal::with('employee')->latest()->get();$employees=Employee::active()->where('employment_type','Contract')->get();return view('compliance.renewals',compact('renewals','employees'));} public function requestRenewal(Request $r):RedirectResponse{$d=$r->validate(['employee_id'=>'required|exists:employees,id','proposed_end_date'=>'required|date','reason'=>'required|string|max:1000','document'=>'nullable|file|max:5120|mimes:pdf,doc,docx']);$e=Employee::findOrFail($d['employee_id']);$path=$r->hasFile('document')?$r->file('document')->store('contracts/renewals','public'):null;ContractRenewal::create(['employee_id'=>$e->id,'current_end_date'=>$e->contract_end_date,'proposed_end_date'=>$d['proposed_end_date'],'reason'=>$d['reason'],'document_path'=>$path,'requested_by'=>$r->user()->id]);return back()->with('success','Renewal request submitted.');} public function renewApprove(Request $r,ContractRenewal $renewal):RedirectResponse{$renewal->update(['status'=>'Approved','reviewed_by'=>$r->user()->id,'reviewed_at'=>now()]);$renewal->employee->update(['contract_end_date'=>$renewal->proposed_end_date]);return back()->with('success','Contract renewal approved.');} public function grievances():View{$grievances=Grievance::with(['employee','assignee'])->latest()->get();return view('compliance.grievances',compact('grievances'));} public function grievanceStore(Request $r):RedirectResponse{$d=$r->validate(['subject'=>'required|string|max:180','category'=>'nullable|string|max:80','description'=>'required|string|max:5000','evidence'=>'nullable|file|max:5120|mimes:pdf,doc,docx,jpg,jpeg,png']);$path=$r->hasFile('evidence')?$r->file('evidence')->store('grievances','private'):null;Grievance::create($d+['evidence_path'=>$path,'submitted_by'=>$r->user()->id,'employee_id'=>$r->user()->employee_id]);return back()->with('success','Confidential grievance submitted.');} }
